        "summary": "Call your local Community Action Agency to get on the waiting list, no online application available.",
        "steps": [
          {
            "step": 1,
            "title": "Contact your local Community Action Agency",
            "description": "Each county has a different provider. Use the contact numbers below to reach your area's weatherization program directly."
          },
          {
            "step": 2,
            "title": "Complete intake interview",
            "description": "Provide household income information and basic details about your loved one's home and energy costs over the phone."
          },
          {
            "step": 3,
            "title": "Submit required documents",
            "description": "Mail or deliver application form, income verification, ID copies, and recent utility bills to your local agency."
          },
          {
            "step": 4,
            "title": "Wait for energy audit scheduling",
            "description": "Your loved one will be placed on a waiting list. Priority households (seniors 60+, people with disabilities) may get faster service."
          },
          {
            "step": 5,
            "title": "Energy audit and work approval",
            "description": "A certified auditor inspects the home to determine which weatherization measures will be most cost-effective."
          },
          {
            "step": 6,
            "title": "Weatherization work completed",
            "description": "Certified contractors perform approved work including insulation, air sealing, and heating system improvements at no cost."
          }
        ],
        "processingTime": "Households are placed on a waiting service list after initial contact",
